
// ==========================================
// FUNCIONES DE CONTROL DEL VISUALIZADOR Y ANDAS
// ==========================================
window.cambiarAndaVisualizador = function(idAnda) {
  window.andaSeleccionadaId = idAnda;
  const select = document.getElementById("select-anda-visualizar");
  if (select && select.value != idAnda) select.value = idAnda;

  const anda = (window.listaAndasGlobal || []).find(a => a.ID_Anda == idAnda);
  if (anda) {
    const brazos = parseInt(anda.Cantidad_Brazos, 10) || 40;
    const turnos = parseInt(anda.Cantidad_Turnos, 10) || 5;
    const cupoMax = anda.Cupo_Maximo ? parseInt(anda.Cupo_Maximo, 10) : (brazos * turnos);
    const totalInscritos = parseInt(anda.Total_Inscritos, 10) || 0;
    const disponibles = Math.max(0, cupoMax - totalInscritos);
    const porcentaje = cupoMax > 0 ? Math.min(100, Math.round((totalInscritos / cupoMax) * 100)) : 0;

    // Badges en cabecera
    const badgeBrazos = document.getElementById("badge-total-brazos");
    if (badgeBrazos) badgeBrazos.innerText = brazos + " Brazos (" + turnos + " Turnos)";

    const badgeCupo = document.getElementById("badge-cupo-inscritos");
    if (badgeCupo) {
      badgeCupo.innerText = totalInscritos + " / " + cupoMax + " Inscritos";
      badgeCupo.className = "badge font-cinzel px-3 py-2 " + (disponibles === 0 ? "bg-danger text-white" : "bg-info text-dark");
    }
    
    // Panel de métricas y barra de progreso
    const statInscritos = document.getElementById("stat-total-inscritos");
    if (statInscritos) statInscritos.innerText = totalInscritos;

    const statDisponibles = document.getElementById("stat-cupos-disponibles");
    if (statDisponibles) {
      statDisponibles.innerText = disponibles;
      statDisponibles.className = "fs-5 fw-bold " + (disponibles === 0 ? "text-danger" : "text-success");
    }

    const statMax = document.getElementById("stat-capacidad-maxima");
    if (statMax) statMax.innerText = cupoMax;

    const statPorc = document.getElementById("stat-porcentaje-texto");
    if (statPorc) statPorc.innerText = porcentaje + "% ocupado";

    const statBarra = document.getElementById("stat-barra-progreso");
    if (statBarra) {
      statBarra.style.width = porcentaje + "%";
      statBarra.setAttribute("aria-valuenow", porcentaje);
      statBarra.className = "progress-bar " + (porcentaje >= 100 ? "bg-danger" : (porcentaje >= 80 ? "bg-warning" : "bg-morado"));
    }

    const desc = document.getElementById("descripcion-cortejo-activa");
    if (desc) desc.innerText = anda.Descripcion || ("Cortejo Procesional - Temporada " + (anda.Anio_Temporada || 2026));

    // Ajustar opciones del select de turnos
    const selTurno = document.getElementById("select-turno-visualizar");
    if (selTurno) {
      const turnos = anda.Cantidad_Turnos || 5;
      selTurno.innerHTML = "";
      for (let t = 1; t <= turnos; t++) {
        selTurno.innerHTML += `<option value="${t}">Turno ${t}</option>`;
      }
    }
  }

  if (typeof cargarDistribucionAnda === 'function') {
    cargarDistribucionAnda();
  }
};

window.abrirModalEditarAnda = function() {
  const select = document.getElementById("select-anda-visualizar");
  const idAnda = select ? select.value : (window.andaSeleccionadaId || 1);
  const anda = (window.listaAndasGlobal || []).find(a => a.ID_Anda == idAnda);

  if (!anda) {
    alert("Por favor selecciona un anda válida para editar.");
    return;
  }

  document.getElementById("modalEditarAndaTitulo").innerText = "Editar Anda Procesional";
  document.getElementById("edit-anda-id").value = anda.ID_Anda;
  document.getElementById("edit-anda-nombre").value = anda.Nombre_Anda || '';
  document.getElementById("edit-anda-brazos").value = anda.Cantidad_Brazos || 40;
  document.getElementById("edit-anda-turnos").value = anda.Cantidad_Turnos || 5;
  document.getElementById("edit-anda-anio").value = anda.Anio_Temporada || 2026;
  document.getElementById("edit-anda-descripcion").value = anda.Descripcion || '';

  const modalEl = document.getElementById("modalEditarAnda");
  const modal = bootstrap.Modal.getInstance(modalEl) || new bootstrap.Modal(modalEl);
  modal.show();
};

window.abrirModalCrearAnda = function() {
  document.getElementById("modalEditarAndaTitulo").innerText = "Registrar Nueva Anda Procesional";
  document.getElementById("edit-anda-id").value = "";
  document.getElementById("edit-anda-nombre").value = "";
  document.getElementById("edit-anda-brazos").value = 40;
  document.getElementById("edit-anda-turnos").value = 5;
  document.getElementById("edit-anda-anio").value = 2026;
  document.getElementById("edit-anda-descripcion").value = "";

  const modalEl = document.getElementById("modalEditarAnda");
  const modal = bootstrap.Modal.getInstance(modalEl) || new bootstrap.Modal(modalEl);
  modal.show();
};

window.guardarDatosAnda = async function(e) {
  e.preventDefault();
  const idInput = document.getElementById("edit-anda-id");
  let id = idInput ? idInput.value : "";
  if (!id && window.andaSeleccionadaId) {
    id = window.andaSeleccionadaId;
  }

  const nombre = document.getElementById("edit-anda-nombre").value.trim();
  const brazos = parseInt(document.getElementById("edit-anda-brazos").value, 10);
  const turnos = parseInt(document.getElementById("edit-anda-turnos").value, 10);
  const anio = parseInt(document.getElementById("edit-anda-anio").value, 10) || 2026;
  const desc = document.getElementById("edit-anda-descripcion").value.trim();

  const payload = {
    nombreAnda: nombre,
    cantidadBrazos: brazos,
    cantidadTurnos: turnos,
    anioTemporada: anio,
    descripcion: desc
  };

  const url = id ? `/andas/${id}` : '/andas';
  const metodo = id ? 'PUT' : 'POST';

  try {
    const res = await fetchAutenticado(url, {
      method: metodo,
      body: JSON.stringify(payload)
    });

    const data = await res.json().catch(() => ({}));
    if (!res.ok) {
      intentosFallidosLogin++;
      if (intentosFallidosLogin >= 5) {
        loginBloqueadoHasta = Date.now() + 30000; // 30 segundos
        intentosFallidosLogin = 0;
        if (alerta) {
          alerta.textContent = "Has superado los 5 intentos. Espera 30 segundos para volver a intentar.";
          alerta.classList.remove("d-none");
        }
        const btnLogin = document.querySelector("#modalLogin button[type='submit']");
        if (btnLogin) {
          btnLogin.disabled = true;
          let tiempoRestante = 30;
          const intervalo = setInterval(() => {
            tiempoRestante--;
            btnLogin.textContent = `Espera (${tiempoRestante}s)`;
            if (tiempoRestante <= 0) {
              clearInterval(intervalo);
              btnLogin.disabled = false;
              btnLogin.textContent = "INGRESAR AL SISTEMA";
              if (alerta) alerta.classList.add("d-none");
            }
          }, 1000);
        }
      }
      throw new Error(data.mensaje || data.error || ("Error HTTP " + res.status));
    }

    alert(id ? "Anda actualizada correctamente." : "Anda registrada exitosamente.");
    const modalEl = document.getElementById("modalEditarAnda");
    if (modalEl && typeof bootstrap !== 'undefined') {
      const modal = bootstrap.Modal.getInstance(modalEl);
      if (modal) modal.hide();
    }

    if (typeof cargarAndasDisponibles === 'function') {
      await cargarAndasDisponibles();
    }
  } catch (err) {
    alert("Error al guardar anda: " + err.message);
  }
};


window.cargarAndasDisponibles = async function() {
  try {
    const res = await fetchAutenticado("/andas");
    if (!res.ok) throw new Error("HTTP error " + res.status);
    const data = await res.json();
    const lista = Array.isArray(data) ? data : (data.andas || []);
    window.listaAndasGlobal = lista;

    const select = document.getElementById("select-anda-visualizar");
    if (select) {
      if (lista.length === 0) {
        select.innerHTML = '<option value="">No hay andas activas</option>';
      } else {
        select.innerHTML = lista.map(a => 
          `<option value="${a.ID_Anda}">${a.Nombre_Anda} (${a.Cantidad_Brazos} brazos / ${a.Cantidad_Turnos} turnos - ${a.Anio_Temporada || 2026})</option>`
        ).join("");

        if (!window.andaSeleccionadaId || !lista.some(a => a.ID_Anda == window.andaSeleccionadaId)) {
          window.andaSeleccionadaId = lista[0].ID_Anda;
        }
        select.value = window.andaSeleccionadaId;
      }
    }

    if (typeof window.cambiarAndaVisualizador === 'function' && window.andaSeleccionadaId) {
      window.cambiarAndaVisualizador(window.andaSeleccionadaId);
    } else if (typeof cargarDistribucionAnda === 'function') {
      cargarDistribucionAnda();
    }
  } catch (err) {
    console.error("Error cargando andas:", err);
    const select = document.getElementById("select-anda-visualizar");
    if (select) select.innerHTML = '<option value="">Error al cargar andas</option>';
  }
};

const API_URL = '/api';

// Usar sessionStorage para que la sesión muera al cerrar las pestañas/navegador
let tokenActual = sessionStorage.getItem('token_hermandad') || null;
let usuarioActual = JSON.parse(sessionStorage.getItem('usuario_hermandad') || '{}');

document.addEventListener('DOMContentLoaded', () => {
  if (tokenActual) {
    iniciarSesionEnFrontend(tokenActual, usuarioActual);

    // Lanzar ventana modal de bienvenida institucional
    if (typeof window.mostrarBienvenidaLogin === 'function') {
      window.mostrarBienvenidaLogin(usuarioActual);
    }
  } else {
    navegarA('vista-bienvenida');
  }

  // Formularios
  document.getElementById('form-login').addEventListener('submit', manejarLogin);
  document.getElementById('form-nuevo-devoto').addEventListener('submit', manejarRegistroDevoto);
  const formAsignar = document.getElementById('form-asignar-turno') || document.getElementById('form-cobro-turno');
  if (formAsignar && typeof manejarCobroTurno === 'function') formAsignar.addEventListener('submit', manejarCobroTurno);
  else if (formAsignar && typeof manejarAsignarTurno === 'function') formAsignar.addEventListener('submit', manejarAsignarTurno);
  document.getElementById('form-ofrenda').addEventListener('submit', manejarOfrenda);
  document.getElementById('form-egreso').addEventListener('submit', manejarEgreso);
  document.getElementById('form-nuevo-usuario').addEventListener('submit', manejarCrearUsuario);
});

// 1. Navegación SPA

function navegarA(vistaId) {
  // 1. Ocultar todas las secciones SPA
  document.querySelectorAll('.seccion-spa, section').forEach(s => s.classList.add('d-none'));

  // 2. Mostrar la sección seleccionada
  const destino = document.getElementById(vistaId);
  if (destino) {
    destino.classList.remove('d-none');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  // 3. Resaltar enlace activo en navbar
  document.querySelectorAll('.navbar-nav .nav-link').forEach(link => {
    link.classList.remove('active');
  });
  const linkActivo = document.querySelector(`[onclick="navegarA('${vistaId}')"]`);
  if (linkActivo) linkActivo.classList.add('active');

  // 4. Cargar datos correspondientes
  if (vistaId === 'vista-devotos' && typeof cargarDevotos === 'function') cargarDevotos();
  if (vistaId === 'vista-caja' && typeof cargarSelectDevotos === 'function') cargarSelectDevotos();
  if (vistaId === 'vista-corte-diario' && typeof cargarMisCobrosDia === 'function') cargarMisCobrosDia();
  if (vistaId === 'vista-anda') { (window.cargarAndasDisponibles || cargarAndasDisponibles)(); }
  if (vistaId === 'vista-reportes') {
    if (typeof cargarReporteFinanciero === 'function') cargarReporteFinanciero();
    else if (typeof cargarReportes === 'function') cargarReportes();
  }
  if (vistaId === 'vista-usuarios' && typeof cargarUsuarios === 'function') cargarUsuarios();
  if (vistaId === 'vista-auditoria' && typeof cargarAuditoria === 'function') cargarAuditoria();
  if (vistaId === 'vista-enseres' && typeof cargarEnseres === 'function') cargarEnseres();
}

// 2. Autenticación y Cierre de Sesión

let intentosFallidosLogin = 0;
let loginBloqueadoHasta = 0;

async function manejarLogin(e) {
  e.preventDefault();
  const ahora = Date.now();
  const alerta = document.getElementById("login-alerta");
  const btnLogin = document.querySelector("#modalLogin button[type='submit']");

  // 1. Validar si el usuario está en tiempo de espera (cooldown)
  if (ahora < loginBloqueadoHasta) {
    const segundosRestantes = Math.ceil((loginBloqueadoHasta - ahora) / 1000);
    if (alerta) {
      alerta.textContent = `Demasiados intentos fallidos. Espera ${segundosRestantes} segundos.`;
      alerta.classList.remove("d-none");
    }
    return;
  }

  const correoEl = document.getElementById("login-correo");
  const passEl = document.getElementById("login-password");
  const correo = correoEl ? correoEl.value.trim() : "";
  const password = passEl ? passEl.value : "";

  try {
    const res = await fetch(`${API_URL}/auth/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ correo, password })
    });
    const data = await res.json();

    if (!res.ok) {
      if (correoEl) { correoEl.value = ""; correoEl.focus(); }
      if (passEl) { passEl.value = ""; }

      intentosFallidosLogin++;

      if (intentosFallidosLogin >= 5) {
        loginBloqueadoHasta = Date.now() + 30000; // 30 segundos
        intentosFallidosLogin = 0;

        if (alerta) {
          alerta.textContent = "Has superado los 5 intentos. Espera 30 segundos para volver a intentar.";
          alerta.classList.remove("d-none");
        }

        if (btnLogin) {
          btnLogin.disabled = true;
          let tiempoRestante = 30;
          const intervalo = setInterval(() => {
            tiempoRestante--;
            btnLogin.textContent = `Espera (${tiempoRestante}s)`;
            if (tiempoRestante <= 0) {
              clearInterval(intervalo);
              btnLogin.disabled = false;
              btnLogin.textContent = "INGRESAR AL SISTEMA";
              if (alerta) alerta.classList.add("d-none");
            }
          }, 1000);
        }
      } else {
        const intentosRestantes = 5 - intentosFallidosLogin;
        if (alerta) {
          alerta.textContent = `${data.mensaje || "Credenciales incorrectas"}. Te quedan ${intentosRestantes} intento(s).`;
          alerta.classList.remove("d-none");
        } else {
          alert(data.mensaje || "Credenciales incorrectas");
        }
      }
      return;
    }

    // Login exitoso: restablecer contadores
    intentosFallidosLogin = 0;
    loginBloqueadoHasta = 0;
    if (btnLogin) {
      btnLogin.disabled = false;
      btnLogin.textContent = "INGRESAR AL SISTEMA";
    }

    tokenActual = data.token;
    usuarioActual = data.usuario;

    sessionStorage.setItem('token_hermandad', tokenActual);
    sessionStorage.setItem('usuario_hermandad', JSON.stringify(usuarioActual));
    sessionStorage.setItem('usuario', JSON.stringify(usuarioActual));
    localStorage.setItem('usuario', JSON.stringify(usuarioActual));

    if (correoEl) correoEl.value = '';
    if (passEl) passEl.value = '';
    if (alerta) alerta.classList.add('d-none');

    iniciarSesionEnFrontend(tokenActual, usuarioActual);
  } catch (error) {
    console.error('Error durante el login:', error);
    if (alerta) {
      alerta.textContent = 'Error de conexión con el servidor';
      alerta.classList.remove('d-none');
    } else {
      alert('Error de conexión con el servidor');
    }
  }
}

function iniciarSesionEnFrontend(token, usuario) {
  sessionStorage.setItem("usuario", JSON.stringify(usuario));
  sessionStorage.setItem("usuario_hermandad", JSON.stringify(usuario));
  

  const modalEl = document.getElementById("modalLogin");
  if (modalEl && typeof bootstrap !== "undefined") {
    const modalInstancia = bootstrap.Modal.getInstance(modalEl) || new bootstrap.Modal(modalEl);
    modalInstancia.hide();
  }

  document.querySelectorAll(".modal-backdrop").forEach(b => b.remove());
  document.body.classList.remove("modal-open");
  document.body.style.removeProperty("padding-right");

  if (typeof actualizarNavPorSesion === "function") {
    actualizarNavPorSesion();
  }

  const idRol = Number(usuario.idRol || usuario.ID_Rol || 0);
  navegarA("vista-bienvenida");

  // Disparar ventana modal de bienvenida tras completar la transición de vista
  setTimeout(() => {
    if (typeof window.mostrarBienvenidaLogin === 'function') {
      window.mostrarBienvenidaLogin(usuario);
    }
  }, 300);
}

function cerrarSesion() {
  sessionStorage.clear();
  localStorage.clear();
  tokenActual = null;
  usuarioActual = {};

  const formLogin = document.getElementById("form-login");
  if (formLogin) formLogin.reset();

  if (typeof actualizarNavPorSesion === "function") {
    actualizarNavPorSesion();
  } else {
    location.reload();
  }
  navegarA("vista-bienvenida");
  const inputCorreo = document.getElementById('login-correo');
  if (inputCorreo) inputCorreo.value = '';
  const inputPass = document.getElementById('login-password');
  if (inputPass) inputPass.value = '';

  const alerta = document.getElementById('login-alerta');
  if (alerta) {
    alerta.textContent = '';
    alerta.classList.add('d-none');
  }

  document.getElementById('navbar-principal')?.classList.add('d-none');
  navegarA('vista-bienvenida');
}

async function fetchAutenticado(endpoint, opciones = {}) {
  const headers = {
    ...opciones.headers,
    'Authorization': `Bearer ${tokenActual}`,
    'Content-Type': 'application/json'
  };
  return await fetch(`${API_URL}${endpoint}`, { ...opciones, headers });
}

// 3. Devotos
// 2. Padrón de Devotos con búsqueda y filtros
window.todosLosDevotos = [];

function renderizarTablaDevotos(devotos) {
  const tbody = document.getElementById('tabla-devotos-body');
  const contador = document.getElementById('contador-devotos-padron');
  if (!tbody) return;
  tbody.innerHTML = '';

  if (contador) {
    const total = window.todosLosDevotos.length;
    const filtrados = devotos.length;
    contador.innerHTML = `<i class="bi bi-person-check-fill me-1 text-morado"></i> Mostrando <strong>${filtrados}</strong> de <strong>${total}</strong> devotos registrados`;
  }

  if (!devotos || devotos.length === 0) {
    tbody.innerHTML = '<tr><td colspan="7" class="text-center text-muted py-4">No se encontraron devotos que coincidan con la búsqueda</td></tr>';
    return;
  }

  const esAdminOSec = usuarioActual && (usuarioActual.idRol === 1 || usuarioActual.idRol === 2);

  devotos.forEach(d => {
    const nombreCompleto = `${d.Nombres || ''} ${d.Apellidos || ''}`.trim();
    tbody.innerHTML += `
      <tr>
        <td><span class="badge bg-light text-dark font-monospace border">${d.DPI || 'S/DPI'}</span></td>
        <td class="fw-semibold text-morado">${nombreCompleto}</td>
        <td><i class="bi bi-telephone text-muted me-1 small"></i>${d.Telefono || 'N/A'}</td>
        <td class="small text-muted">${d.Correo_Electronico || 'N/A'}</td>
        <td><span class="badge bg-info text-dark">${d.Estatura_Hombro_cm || 0} cm</span></td>
        <td><span class="badge bg-success">Activo</span></td>
        ${esAdminOSec ? 
          `<td class="text-end"><button class="btn btn-sm btn-outline-morado fw-bold" onclick="abrirEditarDevoto(${d.ID_Devoto})"><i class="bi bi-pencil-square me-1"></i>Editar</button></td>` : 
          '<td class="text-end"></td>'}
      </tr>
    `;
  });
}

function filtrarDevotos() {
  const input = document.getElementById('input-buscar-devoto');
  const termino = (input?.value || '').trim().toLowerCase();

  if (!termino) {
    renderizarTablaDevotos(window.todosLosDevotos);
    return;
  }

  const resultado = window.todosLosDevotos.filter(d => {
    const dpi = String(d.DPI || '').toLowerCase();
    const nombres = String(d.Nombres || '').toLowerCase();
    const apellidos = String(d.Apellidos || '').toLowerCase();
    const nombreCompleto = `${nombres} ${apellidos}`;
    const telefono = String(d.Telefono || '').toLowerCase();

    return dpi.includes(termino) || 
           nombreCompleto.includes(termino) || 
           telefono.includes(termino);
  });

  renderizarTablaDevotos(resultado);
}

function limpiarBuscadorDevotos() {
  const input = document.getElementById('input-buscar-devoto');
  if (input) {
    input.value = '';
    input.focus();
  }
  renderizarTablaDevotos(window.todosLosDevotos);
}

window.filtrarDevotos = filtrarDevotos;
window.limpiarBuscadorDevotos = limpiarBuscadorDevotos;

async function cargarDevotos() {
  const tbody = document.getElementById('tabla-devotos-body');
  try {
    const res = await fetchAutenticado('/devotos');
    const data = await res.json();
    window.todosLosDevotos = data.devotos || [];

    // Limpiar el campo de búsqueda al volver a cargar la vista
    const input = document.getElementById('input-buscar-devoto');
    if (input) {
      input.value = '';
    }
    renderizarTablaDevotos(window.todosLosDevotos);
  } catch (err) {
    console.error('Error al cargar devotos:', err);
    if (tbody) {
      tbody.innerHTML = '<tr><td colspan="7" class="text-center text-danger py-4">Error al cargar la lista de devotos</td></tr>';
    }
  }
}


async function manejarRegistroDevoto(e) {
  e.preventDefault();
  const dpi = document.getElementById('devoto-dpi').value;
  const nombres = document.getElementById('devoto-nombres').value;
  const apellidos = document.getElementById('devoto-apellidos').value;
  const telefono = document.getElementById('devoto-telefono').value;
  const correo = document.getElementById('devoto-correo').value;
  const elAlt = document.getElementById("devoto-altura") || document.getElementById("devoto-estatura");
  const estaturaHombroCm = elAlt ? parseFloat(elAlt.value) : 0;

  const res = await fetchAutenticado('/devotos', {
    method: 'POST',
    body: JSON.stringify({ dpi, nombres, apellidos, telefono, correo, estaturaHombroCm })
  });
  const data = await res.json();

  if (!res.ok) {
    alert(data.mensaje || 'Error al guardar devoto');
    return;
  }

  alert('Devoto registrado con éxito en el padrón');
  document.getElementById('form-nuevo-devoto').reset();
  bootstrap.Modal.getInstance(document.getElementById('modalNuevoDevoto')).hide();
  cargarDevotos();
}

// 4. Operaciones de Caja

// 4. Operaciones de Caja - Búsqueda de Devotos por DPI, Nombre o Teléfono
window.listaDevotosCaja = [];

function poblarSelectDevotos(lista, idSeleccionado = '') {
  const selectDevoto = document.getElementById('cobro-devoto-select') || document.getElementById('devoto-select');
  const badgeContador = document.getElementById('contador-filtro-caja');
  if (!selectDevoto) return;

  selectDevoto.innerHTML = '';
  const total = window.listaDevotosCaja.length;

  if (badgeContador) {
    badgeContador.textContent = `${lista.length} de ${total}`;
  }

  if (lista.length === 0) {
    selectDevoto.innerHTML = '<option value="">No hay devotos coincidentes</option>';
    return;
  }

  selectDevoto.innerHTML = '<option value="">Seleccione un cargador...</option>';
  lista.forEach(d => {
    const dpi = d.DPI ? `DPI: ${d.DPI}` : 'S/DPI';
    const tel = d.Telefono ? `Tel: ${d.Telefono}` : 'S/Tel';
    const opt = document.createElement('option');
    opt.value = d.ID_Devoto;
    opt.textContent = `${d.Nombres} ${d.Apellidos} | ${dpi} | ${tel} (${d.Estatura_Hombro_cm} cm)`;
    if (String(d.ID_Devoto) === String(idSeleccionado)) {
      opt.selected = true;
    }
    selectDevoto.appendChild(opt);
  });

  // Si tras la búsqueda solo queda 1 devoto coincidente, auto-seleccionarlo
  if (lista.length === 1) {
    selectDevoto.selectedIndex = 1;
  }
}

function filtrarSelectDevotos() {
  const input = document.getElementById('filtro-cobro-devoto');
  const termino = (input?.value || '').trim().toLowerCase();

  if (!termino) {
    poblarSelectDevotos(window.listaDevotosCaja);
    return;
  }

  const filtrados = window.listaDevotosCaja.filter(d => {
    const dpi = String(d.DPI || '').toLowerCase();
    const nombre = `${d.Nombres || ''} ${d.Apellidos || ''}`.toLowerCase();
    const tel = String(d.Telefono || '').toLowerCase();

    return dpi.includes(termino) || nombre.includes(termino) || tel.includes(termino);
  });

  poblarSelectDevotos(filtrados);
}

function limpiarFiltroCobroDevoto() {
  const input = document.getElementById('filtro-cobro-devoto');
  if (input) {
    input.value = '';
    input.focus();
  }
  poblarSelectDevotos(window.listaDevotosCaja);
}

window.filtrarSelectDevotos = filtrarSelectDevotos;
window.limpiarFiltroCobroDevoto = limpiarFiltroCobroDevoto;

async function cargarSelectDevotos() {
  const selectDevoto = document.getElementById('cobro-devoto-select') || document.getElementById('devoto-select');
  const selectAnda = document.getElementById('cobro-anda-select');

  // Limpiar el input de búsqueda cada vez que se recarga la caja
  const inputFiltro = document.getElementById('filtro-cobro-devoto');
  if (inputFiltro) inputFiltro.value = '';

  if (selectDevoto) {
    try {
      const res = await fetchAutenticado('/devotos');
      const data = await res.json();
      window.listaDevotosCaja = data.devotos || [];
      poblarSelectDevotos(window.listaDevotosCaja);
    } catch (err) {
      console.error('Error cargando devotos en caja:', err);
      selectDevoto.innerHTML = '<option value="">Error al cargar devotos</option>';
    }
  }

  if (selectAnda) {
    try {
      const res = await fetchAutenticado('/andas');
      const data = await res.json();
      selectAnda.innerHTML = '<option value="">Seleccione el Anda...</option>';
      (data.andas || []).forEach(a => {
        selectAnda.innerHTML += `<option value="${a.ID_Anda}">${a.Nombre_Anda} (${a.Cantidad_Brazos} brazos - ${a.Cantidad_Turnos} turnos)</option>`;
      });
    } catch (err) {
      console.error('Error cargando andas en caja:', err);
    }
  }
}


async function manejarCobroTurno(e) {
  e.preventDefault();
  const idDevoto = document.getElementById('cobro-devoto-select')?.value;
  const idAnda = document.getElementById('cobro-anda-select')?.value;
  const montoQuetzales = parseFloat(document.getElementById('cobro-cuota')?.value || '50.00');

  if (!idDevoto || !idAnda) {
    alert('Por favor selecciona tanto el cargador como el anda procesional.');
    return;
  }

  const selectAnda = document.getElementById('cobro-anda-select');
  const optAnda = selectAnda ? selectAnda.options[selectAnda.selectedIndex] : null;
  if (optAnda && optAnda.dataset && optAnda.dataset.abiertas === '0') {
    alert('Las inscripciones para este cortejo procesional están CERRADAS actualmente.');
    return;
  }

  try {
    const res = await fetchAutenticado('/finanzas/cobro-inscripcion', {
      method: 'POST',
      body: JSON.stringify({ idDevoto, idAnda, montoQuetzales })
    });
    const data = await res.json();

    if (!res.ok) {
      alert(data.mensaje || 'Error al procesar el cobro');
      return;
    }

    alert(data.mensaje);
    if (data.comprobante) {
      generarReciboInscripcionPDF(data.comprobante);
    }
    document.getElementById('form-cobro-turno')?.reset();
    if (typeof cargarMisCobrosDia === 'function') cargarMisCobrosDia();
    cargarSelectDevotos();
  } catch (err) {
    console.error('Error en cobro de turno:', err);
    alert('Error de conexión al procesar el cobro.');
  }
}
async function manejarAsignarTurno(e) { return manejarCobroTurno(e); }


async function manejarOfrenda(e) {
  e.preventDefault();
  const nombreBienhechor = document.getElementById('ofrenda-donante').value;
  const conceptoDescripcion = document.getElementById('ofrenda-concepto').value;
  const montoQuetzales = parseFloat(document.getElementById('ofrenda-monto').value);
  const metodoPago = document.getElementById('ofrenda-metodo').value;

  const res = await fetchAutenticado('/finanzas/ofrenda', {
    method: 'POST',
    body: JSON.stringify({ nombreBienhechor, conceptoDescripcion, montoQuetzales, metodoPago })
  });
  const data = await res.json();

  if (!res.ok) {
    alert(data.mensaje || 'Error al registrar ofrenda');
    return;
  }

  alert(`Ofrenda asentada correctamente. Comprobante: ${data.comprobante.numeroRecibo}`);
  document.getElementById('form-ofrenda').reset();
}

async function manejarEgreso(e) {
  e.preventDefault();
  const proveedorBeneficiario = document.getElementById('egreso-proveedor').value;
  const encargadoGasto = document.getElementById('egreso-encargado').value;
  const conceptoGasto = document.getElementById('egreso-concepto').value;
  const montoQuetzales = parseFloat(document.getElementById('egreso-monto').value);
  const numeroFacturaComprobante = document.getElementById('egreso-factura').value || 'S/F';

  const res = await fetchAutenticado('/finanzas/egreso', {
    method: 'POST',
    body: JSON.stringify({ 
      proveedorBeneficiario,
      encargadoGasto,
      conceptoGasto, 
      montoQuetzales, 
      numeroFacturaComprobante 
    })
  });
  const data = await res.json();

  if (!res.ok) {
    alert(data.mensaje || 'Error al liquidar egreso');
    return;
  }

  alert(`Egreso liquidado con éxito. Comprobante: ${data.comprobanteEgreso.numeroComprobante}\nSaldo restante en caja: ${data.comprobanteEgreso.saldoRestanteEnCaja}`);
  if (data.comprobanteEgreso) generarComprobanteEgresoPDF(data.comprobanteEgreso);
  document.getElementById('form-egreso').reset();
}

// 5. Visualizador del Anda
async function cargarDistribucionAnda() {
  const elemAnda = document.getElementById('select-anda-visualizar');
  const idAnda = elemAnda ? elemAnda.value : (window.andaSeleccionadaId || 1);
  if (!idAnda) return;

  const anda = (window.listaAndasGlobal || []).find(a => a.ID_Anda == idAnda);
  const totalBrazos = anda ? (anda.Cantidad_Brazos || 40) : 40;
  const anio = anda ? (anda.Anio_Temporada || 2026) : 2026;

  const elemTurno = document.getElementById('select-turno-visualizar');
  const turno = (elemTurno && elemTurno.value) ? parseInt(elemTurno.value, 10) : 1;

  const contenedorIzq = document.getElementById('contenedor-brazos-izq');
  const contenedorDer = document.getElementById('contenedor-brazos-der');

  if (!contenedorIzq || !contenedorDer) return;

  contenedorIzq.innerHTML = '';
  contenedorDer.innerHTML = '';

  let cargadoresTurno = [];
  try {
    const res = await fetchAutenticado(`/turnos/anda/${idAnda}/${anio}`);
    if (res.ok) {
      const data = await res.json();
      cargadoresTurno = (data.turnos || []).filter(t => t.Numero_Turno == turno);
    }
  } catch (err) {
    console.warn("Datos de turnos no disponibles en este momento:", err);
  }

  // Lado Izquierdo: Números Impares (1, 3, 5, 7, ..., hasta totalBrazos)
  for (let b = 1; b <= totalBrazos; b += 2) {
    const asignado = cargadoresTurno.find(c => c.Brazo_Asignado === b || (c.Numero_Brazo === b && c.Lado_Brazo === 'IZQUIERDO'));
    contenedorIzq.innerHTML += `
      <div class="brazo-slot p-2 border rounded d-flex justify-content-between align-items-center mb-1 ${asignado ? 'bg-primary text-white fw-bold' : 'bg-light'}">
        <span class="fw-bold">Brazo ${b}</span>
        <span class="small">${asignado ? `${asignado.Nombres} ${asignado.Apellidos || ''} (${asignado.Estatura_Hombro_cm || 0} cm)` : '<span class="text-muted">Disponible</span>'}</span>
      </div>
    `;
  }

  // Lado Derecho: Números Pares (2, 4, 6, 8, ..., hasta totalBrazos)
  for (let b = 2; b <= totalBrazos; b += 2) {
    const asignado = cargadoresTurno.find(c => c.Brazo_Asignado === b || (c.Numero_Brazo === b && c.Lado_Brazo === 'DERECHO'));
    contenedorDer.innerHTML += `
      <div class="brazo-slot p-2 border rounded d-flex justify-content-between align-items-center mb-1 ${asignado ? 'bg-success text-white fw-bold' : 'bg-light'}">
        <span class="fw-bold">Brazo ${b}</span>
        <span class="small">${asignado ? `${asignado.Nombres} ${asignado.Apellidos || ''} (${asignado.Estatura_Hombro_cm || 0} cm)` : '<span class="text-muted">Disponible</span>'}</span>
      </div>
    `;
  }
}

